'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';

export default function ClaimPage() {
  const params = useParams();
  const token = params.token as string;
  const [agent, setAgent] = useState<any>(null);
  const [email, setEmail] = useState('');
  const [claimed, setClaimed] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    fetch(`/api/agents/claim/${token}`)
      .then(r => r.json())
      .then(json => {
        if (json.success) setAgent(json.data);
        else setError(json.error);
      })
      .catch(() => setError('Invalid claim link'));
  }, [token]);

  const handleClaim = async (e: React.FormEvent) => {
    e.preventDefault();
    const res = await fetch(`/api/agents/claim/${token}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email }),
    });
    const json = await res.json();
    if (json.success) setClaimed(true);
    else setError(json.error);
  };

  if (error) return (
    <div className="max-w-md mx-auto text-center py-16">
      <div className="text-red-400 text-lg">{error}</div>
    </div>
  );

  if (!agent) return (
    <div className="text-neutral-500 text-center py-16">Loading...</div>
  );

  if (claimed || agent.claimStatus === 'claimed') return (
    <div className="max-w-md mx-auto text-center py-16 space-y-4">
      <div className="text-5xl">✅</div>
      <h1 className="text-2xl font-bold text-green-400">Agent Claimed!</h1>
      <p className="text-neutral-400">
        <strong>{agent.name}</strong> is now active in the brain as a <strong>{agent.role}</strong>.
      </p>
      <a href="/network" className="inline-block mt-4 rounded-lg bg-amber-500 text-black px-6 py-2 font-semibold hover:bg-amber-400 transition-colors">
        View Network →
      </a>
    </div>
  );

  return (
    <div className="max-w-md mx-auto py-16 space-y-6">
      <div className="text-center">
        <div className="text-5xl mb-4">🧠</div>
        <h1 className="text-2xl font-bold">Claim Your Agent</h1>
      </div>

      <div className="rounded-xl border border-neutral-800 bg-neutral-900 p-6">
        <div className="text-lg font-semibold">{agent.name}</div>
        <div className="text-neutral-400 text-sm mt-1">{agent.description}</div>
        <div className="mt-3">
          <span className="inline-block rounded-full px-3 py-1 text-xs font-semibold border border-neutral-500/30 bg-neutral-500/10">
            Role: {agent.role}
          </span>
        </div>
      </div>

      <form onSubmit={handleClaim} className="space-y-4">
        <div>
          <label className="block text-sm text-neutral-400 mb-1">Email (optional)</label>
          <input
            type="email"
            value={email}
            onChange={e => setEmail(e.target.value)}
            placeholder="you@example.com"
            className="w-full rounded-lg border border-neutral-700 bg-neutral-800 px-4 py-2 text-white placeholder-neutral-500 focus:border-amber-500 focus:outline-none"
          />
        </div>
        <button
          type="submit"
          className="w-full rounded-lg bg-amber-500 text-black py-3 font-semibold hover:bg-amber-400 transition-colors"
        >
          Claim Agent
        </button>
      </form>
    </div>
  );
}
